/// <summary>
/// Calculates acceptable trans quantity
/// </summary>
/// <param name = "_errorCorrectionMethods">error correction methods</param>
/// <param name = "_useDefaultOrderSetup">NoYes use default order setup</param>
/// <returns>Quantity</returns>
protected Qty acceptableTransQty(
    InventMovementQuantityErrorCorrectionMethods    _errorCorrectionMethods,
    boolean                                         _useDefaultOrderSetup)
{
    next acceptableTransQty(_errorCorrectionMethods,_useDefaultOrderSetup);
    return this.transQtyUnit() * this.transSign();
}

/// <summary>
/// Extends method setTransQtyUnit
/// </summary>
/// <param name = "_qtyUnit">UnitQty</param>
public void setTransQtyUnit(UnitQty _qtyUnit)
{
    SalesQty        salesQty = salesQuotationLine.SalesQty;

    next setTransQtyUnit(-salesQty);

    if (salesQuotationLine.SalesQty == 0)
    {
        salesQuotationLine.SalesQty = salesQty;
    }
}
